    <Icon
      iconNode={iconNode}
      strokeWidth={strokeWidth}
    >
      <style>
        {`@media screen and (prefers-color-scheme: light) {
          svg { fill: transparent !important; }
        }
        @media screen and (prefers-color-scheme: dark) {
          svg { stroke: #fff; fill: transparent !important; }
