      <Backdrop
        src=""
        outline={false}
        backdropString={`<g mask="url('#gray')">${newSrc}</g>`}
        color="#777"
      />
      <Backdrop
        src={oldSrc}
        backdropString={newSrc}
        color="lime"
      />
      <Backdrop
        src={newSrc}
        backdropString={oldSrc}
        color="red"
      />
      {children}
    </svg>
