        ) {
          // Merge group j into group i
          mergedGroups[i] = [...mergedGroups[i], ...mergedGroups[j]];
          mergedGroups.splice(j, 1);
          changed = true;
          break outer;
        }
      }
    }
  }

  // Return only arrays of IDs
  return mergedGroups.map((groupList) => groupList.map((g) => g.id));
}

