import Fuse, { type FuseOptionKeyObject } from 'fuse.js';
import { shallowRef, computed, Ref } from 'vue';

const useSearch = <T>(
  query: Ref<string>,
  collection: Ref<T[]>,
  keys: FuseOptionKeyObject<T>[] = [],
) => {
  const index = shallowRef(
    new Fuse(collection.value, {
      threshold: 0.2,
      useExtendedSearch: true,
      keys,
    }),
  );

  const results = computed(() => {
    index.value.setCollection(collection.value);

    if (query.value) {
      return index.value
        .search({ $and: query.value.split(' ').filter((t) => !!t) })
        .map((result) => result.item);
    }

    return collection.value;
  });

  return results;
};

export default useSearch;

import { useDebounce } from '@vueuse/core';
import { onMounted, ref, watch } from 'vue';

const useSearchInput = () => {
  const searchInput = ref();
  const searchQuery = ref<string>('');
  const searchQueryDebounced = useDebounce<string>(searchQuery, 200);

  watch(searchQueryDebounced, (searchString) => {
    const newUrl = new URL(window.location.href);

    if (searchString === '') {
      newUrl.searchParams.delete('search');
    } else {
      newUrl.searchParams.set('search', searchString);
      newUrl.hash = '';
    }

    window.history.replaceState({}, '', newUrl);
  });

  onMounted(() => {
    const searchParams = new URLSearchParams(window.location.search);

    if (searchParams.has('search')) {
      searchQuery.value = searchParams.get('search');
    }

    if (searchParams.has('focus')) {
      searchInput.value.focus();
    }
  });

  return {
    searchInput,
    searchQuery,
    searchQueryDebounced,
  };
};

export default useSearchInput;

