import buildLucideIconNode from './buildLucideIconNode';
import type { LucideBuildParams, LucideIconData, LucideIconNode } from './types';

const buildDomElement = (
  document: Document,
  [tagName, attributes, children = []]: LucideIconNode,
): Element => {
  const element = document.createElementNS('http://www.w3.org/2000/svg', tagName);
  for (const [attrName, value] of Object.entries(attributes)) {
    if (value !== undefined && value !== null) {
      element.setAttribute(attrName, String(value));
    }
  }
  for (const node of children) {
    const childNode = buildDomElement(document, node);
    element.appendChild(childNode);
  }
  return element;
};

/**
 * Creates an SvgElement from a Lucide icon object.
 *
 * @param document The document to create the Element in.
 * @param icon The icon to build.
 * @param params Additional build parameters.
 */
function buildLucideIconElement(
  document: Document,
  icon: LucideIconData,
  params: LucideBuildParams = {},
) {
  return buildDomElement(document, buildLucideIconNode(icon, params));
}

export default buildLucideIconElement;

import buildLucideIconNode from './buildLucideIconNode';
import type { LucideBuildParams, LucideIconData, LucideIconNode } from './types';

/**
 * Creates a React-compatible Lucide icon node (an svgson-like format) from a Lucide icon object.
 *
 * @param icon The icon to build.
 * @param params Additional build parameters.
 */
function buildLucideIconForReact(
  icon: LucideIconData,
  params: LucideBuildParams = {},
): LucideIconNode {
  return buildLucideIconNode(icon, {
    ...params,
    attributeNames: {
      ...params.attributeNames,
      class: 'className',
      'stroke-width': 'strokeWidth',
      'stroke-linecap': 'strokeLinecap',
      'stroke-linejoin': 'strokeLinejoin',
      'vector-effect': 'vectorEffect',
    },
  });
}

export default buildLucideIconForReact;

import type { LucideBuildParams, LucideIconData, LucideIconNode, SVGProps } from './types';
import defaultAttributes from './defaultAttributes';
import { mergeClasses } from '../utils/mergeClasses';

function isDefined<T>(value: T | null | undefined): value is T {
  return value !== null && value !== undefined;
}

/**
 * Creates a Lucide icon node (an svgson-like format) from a Lucide icon object.
 *
 * @param icon The icon to build.
 * @param params Additional build parameters.
 */
function buildLucideIconNode(icon: LucideIconData, params: LucideBuildParams = {}): LucideIconNode {
  const attributeNames = params.attributeNames ?? {};
  const getAttributeName = (attributeName: string) =>
    attributeNames[attributeName] ?? attributeName;

  const viewBoxWidth = icon.size ?? icon.width ?? defaultAttributes['width'];
  const viewBoxHeight = icon.size ?? icon.height ?? defaultAttributes['height'];
  const aliasClassNames =
    icon.aliases
      ?.filter((alias: string): alias is string => typeof alias === 'string' && alias.trim() !== '')
      .map((alias: string) => `lucide-${alias}`) ?? [];
  const iconClassNames = [...(icon.name ? [`lucide-${icon.name}`] : []), ...aliasClassNames];
  const classNamesFromClassName = params.className?.split(' ').filter(Boolean) ?? [];
  const className =
    params.includeDefaultClasses === false
      ? mergeClasses(...classNamesFromClassName)
      : mergeClasses('lucide', ...iconClassNames, ...classNamesFromClassName);

  const calculatedStrokeWidth = params.absoluteStrokeWidth
    ? (Number(params.strokeWidth ?? defaultAttributes['stroke-width']) *
        Number(icon.size ?? icon.width ?? defaultAttributes['width'])) /
      Number(params.size ?? params.width ?? defaultAttributes['width'])
    : (params.strokeWidth ?? defaultAttributes['stroke-width']);

  const attributes = {
    ...Object.entries(defaultAttributes).reduce((attrs, [attrName, value]) => {
      attrs[getAttributeName(attrName)] = value;
      return attrs;
    }, {} as SVGProps),
    ...('color' in params &&
      params.color && {
        [getAttributeName('stroke')]: params.color,
      }),
    ...('size' in params &&
      isDefined(params.size) && {
        [getAttributeName('width')]: params.size,
        [getAttributeName('height')]: params.size,
      }),
    ...('width' in params &&
      isDefined(params.width) && {
        [getAttributeName('width')]: params.width,
      }),
    ...('height' in params &&
      isDefined(params.height) && {
        [getAttributeName('height')]: params.height,
      }),
    [getAttributeName('stroke-width')]: calculatedStrokeWidth,
    ...(className && {
      [getAttributeName('class')]: className,
    }),
    [getAttributeName('viewBox')]: `0 0 ${viewBoxWidth} ${viewBoxHeight}`,
    ...(params.hasA11yProp === false
      ? {
          [getAttributeName('aria-hidden')]: 'true',
        }
      : {}),
    ...('attributes' in params && params.attributes),
  };

  return [
    'svg',
    attributes,
    icon.node.map((child): LucideIconNode => {
      const [name, attrs, children] = child;
      const nextAttrs = params.nonScalingStroke
        ? { [getAttributeName('vector-effect')]: 'non-scaling-stroke', ...attrs }
        : attrs;

      return children ? [name, nextAttrs, children] : [name, nextAttrs];
    }),
  ];
}

export default buildLucideIconNode;

