import path from 'path';
import { getCurrentDirPath } from '../../tools/build-helpers/helpers.ts';
import { renameIcon } from './renameIcon.function.mts';

async function main() {
  const oldName = path.basename(process.argv[2]).replace(/\.[^/.]+$/, '');
  const newName = path.basename(process.argv[3]).replace(/\.[^/.]+$/, '');

  if (!newName || !oldName) {
    console.error('Usage: node ./scripts/renameIcon.mjs <oldIcon> <newIcon>');
    process.exit(1);
  }
  if (oldName === newName) {
    console.error('ERROR: Old name and new name are the same');
    process.exit(1);
  }

  try {
    const currentDir = getCurrentDirPath(import.meta.url);
    const ICONS_DIR = path.resolve(currentDir, '../../icons');
    await renameIcon(ICONS_DIR, oldName, newName);
  } catch (err) {
    if(err instanceof Error) {
      console.error(err.message);
    } else {
      console.error('An unexpected error occurred:', err);
    }
    process.exit(1);
  }
}

main();

scripts/rename/renamePattern.mts:
import path from 'path';
import { getCurrentDirPath, readSvgDirectory } from '../../tools/build-helpers/helpers.ts';
import yargs from 'yargs/yargs';
import { hideBin } from 'yargs/helpers';
import { renameIcon } from './renameIcon.function.mts';
import { type Arguments } from 'yargs';

async function main() {
  const currentDir = getCurrentDirPath(import.meta.url);
  const ICONS_DIR = path.resolve(currentDir, '../../icons');
  const svgFiles = await readSvgDirectory(ICONS_DIR);
  const iconNames = svgFiles.map((icon) => icon.split('.')[0]).reverse();
  const argv = (yargs(hideBin(process.argv))
  // @ts-expect-error the builder callback overload is not picked up for a default command
    .usage('$0 <pattern> <replacement>', 'Renames all icons matching a pattern', (yargs) => {
      yargs
        .positional('pattern', {
          type: 'string',
          demandOption: true,
          describe: 'A regular expression, e.g. "^rhombus-(.+)$"',
        })
        .positional('replacement', {
          type: 'string',
          demandOption: true,
          describe: 'A replacement string, e.g. "diamond-\\1"',
        });
    })
    .strictCommands()
    .options({
      'dry-run': { type: 'boolean', default: false, alias: 'd' },
      'add-alias': { type: 'boolean', default: true, alias: 'a' },
    })
    .parse()) as unknown as Arguments<{
      pattern: string;
      replacement: string;
      dryRun: boolean;
      addAlias: boolean;
    }>;

  const pattern = new RegExp(argv?.pattern, 'g');
  const replacement = argv.replacement.replaceAll(/\\([0-9]+)/g, (s, i) => `$${i}`);

  if (!(pattern instanceof RegExp)) {
    console.error(`${pattern} is not a valid regular expression.`);
    process.exit(1);
  }

  for (const oldName of iconNames.filter((name) => pattern.test(name))) {
    const newName = oldName.replaceAll(pattern, replacement);
    console.log(`Renaming ${oldName} => ${newName}`);

    try {
      if (!argv.dryRun) {
        await renameIcon(ICONS_DIR, oldName, newName, false, argv.addAlias);
      }
    } catch (err) {
       if(err instanceof Error) {
      console.error(err.message);
    } else {
      console.error('An unexpected error occurred:', err);
    }
    }
  }
}

main();

scripts/render/processSvg.mts:
import { optimize } from 'svgo';
import * as prettier from 'prettier';
import { parseSync, stringify } from 'svgson';
import DEFAULT_ATTRS from '../../tools/build-icons/render/default-attrs.json' with { type: 'json' };

/**
 * Optimize SVG with `svgo`.
 * @param {string} svg - An SVG string.
 * @returns {Promise<string>} An optimized svg
 */
async function optimizeSvg(svg: string, path: string) {
  const result = optimize(svg, {
    path,
    plugins: [
      {
        name: 'preset-default',
        params: {
          overrides: {
            convertShapeToPath: false,
            mergePaths: false,
          },
        },
      },
      {
        name: 'removeAttrs',
        params: {
          attrs: '(fill|stroke.*)',
        },
      },
    ],
  });

  return result.data;
}

/**
 * Set default attibutes on SVG.
 * @param {string} svg - An SVG string.
 * @returns {string} An SVG string, included with the default attributes.
 */
function setAttrs(svg: string) {
  const contents = parseSync(svg);

  contents.attributes = {
    ...DEFAULT_ATTRS,
    width: String(DEFAULT_ATTRS.width),
    height: String(DEFAULT_ATTRS.height),
    "stroke-width": String(DEFAULT_ATTRS['stroke-width']),
    ...contents.attributes,
  };

  return stringify(contents);
}

/**
 * Process SVG string.
 * @param {string} svg An SVG string.
 * @returns {Promise<string>} An optimized svg
 */
function processSvg(svg: string, path: string) {
  return (
    optimizeSvg(svg, path)
      .then(setAttrs)
      .then((optimizedSvg) => prettier.format(optimizedSvg, { parser: 'babel' }))
      // remove semicolon inserted by prettier
      // because prettier thinks it's formatting JSX not HTML
      .then((svg) => svg.replace(/;/g, ''))
  );
}

export default processSvg;

scripts/updateContributors.mts:
import fs from 'node:fs';
import path from 'path';
import simpleGit from 'simple-git';
import { Octokit } from '@octokit/rest';
import pMemoize from 'p-memoize';

const IGNORED_COMMITS = ['433bbae4f1d4abb50a26306d6679a38ace5c8b78'];
const FETCH_DEPTH = process.env.FETCH_DEPTH || 1000;

const octokit = new Octokit({ auth: process.env.GITHUB_TOKEN });

const git = simpleGit();

const cache = new Map();

const getUserName = pMemoize(
  async (commit) => {
    const { data: fetchedCommit } = await octokit.repos.getCommit({
      owner: 'lucide-icons',
      repo: 'lucide',
      ref: commit.hash,
    });
    if (!fetchedCommit?.author?.login) {
      console.error(`Could not find author name for ${commit.author_email}`);
    }
    return fetchedCommit?.author?.login;
  },
  { cacheKey: ([commit]) => commit.author_email, cache },
);

// Check that a commit changes more than just the icon name
const isCommitRelevant = async (hash: string, file: string) => {
  const summary = await git.diffSummary(['--diff-filter=AM', `${hash}~1`, hash]);
  return summary.files.some(({ file: name }) => name === file);
};

const getContributors = async (file: string, includeCoAuthors?: boolean) => {
  const { all } = await git.log([`HEAD~${FETCH_DEPTH}..`, '--', file]);
  const commits = file.endsWith('.svg')
    ? (
        await Promise.all(all.map(async (commit) => await isCommitRelevant(commit.hash, file) && commit))
      ).filter(Boolean)
    : all;

  const emails = new Map();
  for (let i = commits.length - 1; i >= 0; i -= 1) {
    const commit = commits[i];

    if(!commit || !commit.author_email) {
      console.warn(`Skipping commit without author email: ${JSON.stringify(commit)}`);
      continue;
    }

    if ("hash" in commit && !IGNORED_COMMITS.includes(commit.hash)) {
      if (!emails.has(commit.author_email)) {
        emails.set(commit.author_email, getUserName(commit));
      }
      if (includeCoAuthors) {
        const matches = commit.body.matchAll(
          /(^Author:|^Co-authored-by:)\s+(?<author>[^<]+)\s+<(?<email>[^>]+)>/gm,
        );
         
        for (const match of matches) {
          if (!emails.has(match.groups?.email) && cache.has(match.groups?.email)) {
            emails.set(match.groups?.email, Promise.resolve(cache.get(match.groups?.email)));
          }
        }
      }
    }
  }

  return Promise.all(Array.from(emails.values()));
};

const files = (process.env.CHANGED_FILES?.split(' ') ?? [])
  .map((file) => file.replace('.json', '.svg'))
  .filter((file, idx, arr) => arr.indexOf(file) === idx);

if (!files.every((file) => file.startsWith('icons/'))) {
  console.error("file path must start with 'icons/'");
  process.exit(1);
}

// get all contributors to be able to associate them when they are co authors
await getContributors('icons');

await Promise.all(
  files.map(async (file) => {
    const jsonFile = path.join(process.cwd(), file.replace('.svg', '.json'));
    const json = JSON.parse(fs.readFileSync(jsonFile, 'utf-8'));
    const { tags, categories, aliases, contributors: previousContributors, ...rest } = json;
    const contributors = [
      ...(previousContributors || []),
      ...(await getContributors(file, true)),
    ].filter((contributor, idx, arr) => contributor && arr.indexOf(contributor) === idx);
    fs.writeFileSync(
      jsonFile,
      JSON.stringify(
        {
          $schema: '../icon.schema.json',
          contributors,
          aliases,
          tags,
          categories,
          ...rest,
        },
        null,
        2,
      ) + '\n',
    );
  }),
);

