        (_, groupOpeningTag, iconName) =>
          [
            groupOpeningTag,
            ...readFileSync(path.join(import.meta.dirname, `../icons/${iconName}.svg`), 'utf8')
              .replace(/(<svg)[^>]*>|<\/svg>/g, '')
