          ]
            .map((val) => val.trimEnd())
            .filter(Boolean)
            .join('\n') + '\n',
      ),
    )
    .join('</g>');
  if (oldFileContent !== newFileContent) {
    console.log(`Updating ${fileName}`);
    writeFileSync(fileName, newFileContent);
  }
}

